{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Kanamycin, a closely related aminoglycoside, appeared in CSF after systemic administration in animals with concentrations proportional to blood, directly demonstrating that aminoglycosides can achieve CSF exposure; this supports meaningful CNS access for the query under meningeal inflammation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A sugar-based molecule (THP) rapidly entered the brain after intravenous injection in rabbits, indicating that glycoside-type structures can cross the BBB; although less similar, it supports the possibility of CNS entry for the glycosidic streptomycin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tobramycin, another aminoglycoside, showed very low or unmeasurable CSF concentrations in neonates, illustrating poor baseline CNS penetration of this class; this is contradictory but less applicable because the query is evaluated in tuberculous meningitis, where BBB integrity is compromised.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "A fluorescent aminoglycoside (neomycin-type) distributed to all tissues except brain after IV in healthy mice, confirming that polycationic aminoglycosides do not cross the intact BBB; this is contradictory but does not reflect the inflamed-meninges condition.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: despite being a polar, polycationic aminoglycoside with poor passive BBB penetration, streptomycin is expected to achieve meaningful CNS access in tuberculous meningitis because meningeal inflammation increases BBB permeability; supportive aminoglycoside CSF data (kanamycin) and historical clinical use outweigh the poor-penetration results obtained in non-inflamed states.",
  "evidence_gaps": [
    "No direct streptomycin CSF or brain concentration measurement is present in the provided evidence.",
    "Aminoglycoside evidence is mixed and mostly from non-inflamed or neonatal settings.",
    "No human data for streptomycin under tuberculous meningitis are included in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

